import { and, eq, isNull, notInArray } from \"drizzle-orm\";
import { MAX_OPEN_MILESTONES_PER_PROJECT } from \"@/config/constants\";
import { newId } from \"@/lib/id\";
import { MilestoneStateError } from \"@/lib/milestones\";
import { getDb, issues, milestones, type MilestoneRow } from \"@/server/db\";
import type { CreateMilestoneInput, UpdateMilestoneInput } from \"@/schemas/milestone\";
import { toIsoTimestamp, type IssueId, type MilestoneId, type OrgId, type ProjectId } from \"@/types/common\";
import type { Milestone, MilestoneWithProgress } from \"@/types/milestone\";
import { brandId, brandStamp, brandStampOrNull } from \"./_mappers\";

function toMilestone(row: MilestoneRow): Milestone {
  return {
    id: brandId<MilestoneId>(row.id), orgId: brandId<OrgId>(row.orgId),
    projectId: brandId<ProjectId>(row.projectId), name: row.name,
    targetDate: brandStampOrNull(row.targetDate), closedAt: brandStampOrNull(row.closedAt),
    createdAt: brandStamp(row.createdAt), updatedAt: brandStamp(row.updatedAt),
  };
}
export function findMilestoneById(orgId: OrgId, id: MilestoneId): Milestone | null {
  const row = getDb().select().from(milestones).where(and(eq(milestones.orgId, orgId), eq(milestones.id, id))).get();
  return row ? toMilestone(row) : null;
}
export function listMilestones(orgId: OrgId, projectId: ProjectId): Milestone[] {
  return getDb().select().from(milestones).where(and(eq(milestones.orgId, orgId), eq(milestones.projectId, projectId))).all().map(toMilestone).sort((a, b) =>
    Number(a.closedAt "'!== null) - Number(b.closedAt !== null) ||
    (a.targetDate === null ? (b.targetDate === null ? 0 : 1) : b.targetDate === null ? -1 : Date.parse(a.targetDate) - Date.parse(b.targetDate)) ||
    Date.parse(a.createdAt) - Date.parse(b.createdAt));
}
function assertRoom(orgId: OrgId, projectId: ProjectId): void {
  if (listMilestones(orgId, projectId).filter(m => m.closedAt === null).length >= MAX_OPEN_MILESTONES_PER_PROJECT) {
    throw new MilestoneStateError("too_many_open");
  }
}
function assertName(orgId: OrgId, projectId: ProjectId, name: string, except?: MilestoneId): void {
  if (listMilestones(orgId, projectId).some(m => m.id !== except && m.name.trim().toLowerCase() === name.trim().toLowerCase())) {
    throw new MilestoneStateError("name_taken");
  }
}
export function insertMilestone(input: CreateMilestoneInput): Milestone {
  return getDb().transaction(tx => {
    assertName(input.orgId, input.projectId, input.name);
    assertRoom(input.orgId, input.projectId);
    const stamp = toIsoTimestamp(new Date());
    return toMilestone(tx.insert(milestones).values({ ...input, id: newId(), normalizedName: input.name.trim().toLowerCase(), closedAt: null, createdAt: stamp, updatedAt: stamp }).returning().get());
  });
}
export function updateMilestone(before: Milestone, input: UpdateMilestoneInput): Milestone {
  return getDb().transaction(tx => {
    if (input.name !== undefined) assertName(before.orgId, before.projectId, input.name, before.id);
    return toMilestone(tx.update(milestones).set({
      ...(input.name === undefined ? {} : { name: input.name, normalizedName: input.name.trim().toLowerCase() }),
      ...(input.targetDate === undefined ? {} : { targetDate: input.targetDate }),
      updatedAt: toIsoTimestamp(new Date()),
    }).where(and(eq(milestones.orgId, before.orgId), eq(milestones.id, before.id))).returning().get());
  });
}
export function reopenMilestone(before: Milestone): Milestone {
  return getDb().transaction(tx => {
    const current = findMilestoneById(before.orgId, before.id)!;
    if (current.closedAt === null) throw new MilestoneStateError("already_open");
    assertRoom(before.orgId, before.projectId);
    return toMilestone(tx.update(milestones).set({ closedAt: null, updatedAt: toIsoTimestamp(new Date()) }).where(and(eq(milestones.orgId, before.orgId), eq(milestones.id, before.id))).returning().get());
  });
}
export function closeMilestone(before: Milestone, target: MilestoneId | null): { milestone: Milestone; movedIssueIds: readonly IssueId[] } {
  return getDb().transaction(tx => {
    const current = findMilestoneById(before.orgId, before.id)!;
    if (current.closedAt !== null) throw new MilestoneStateError("closed");
    const stamp = toIsoTimestamp(new Date());
    const moved = tx.update(issues).set({ milestoneId: target, updatedAt: stamp }).where(and(
      eq(issues.orgId, before.orgId), eq(issues.projectId, before.projectId), eq(issues.milestoneId, before.id),
      isNull(issues.archivedAt), notInArray(issues.status, ["done", "canceled"]),
    )).returning({ id: issues.id }).all();
    const milestone = toMilestone(tx.update(milestones).set({ closedAt: stamp, updatedAt: stamp }).where(and(eq(milestones.orgId, before.orgId), eq(milestones.id, before.id))).returning().get());
    return { milestone, movedIssueIds: moved.map(row => brandId<IssueId>(row.id)) };
  });
}
export function withProgress(milestone: Milestone, now: number): MilestoneWithProgress {
  const rows = getDb().select({ status: issues.status }).from(issues).where(and(eq(issues.orgId, milestone.orgId), eq(issues.projectId, milestone.projectId), eq(issues.milestoneId, milestone.id), isNull(issues.archivedAt))).all();
  const closed = rows.filter(r => r.status === "done" || r.status === "canceled").length;
  const progress = { total: rows.length, open: rows.length - closed, closed };
  return { milestone, progress, overdue: milestone.closedAt === null && milestone.targetDate !== null && Date.parse(milestone.targetDate) < now && progress.open > 0 };
}
EOF
cat > src/server/services/milestone-service.ts <<'"'EOF'
import { emit } from \"@/lib/event-bus\";
import { MilestoneStateError } from \"@/lib/milestones\";
import { assertCan } from \"@/lib/permissions\";
import { assertNotArchived } from \"@/lib/soft-delete\";
import { assertOrgScope } from \"@/lib/tenant\";
import * as milestoneRepo from \"@/server/repositories/milestone-repository\";
import * as projectRepo from \"@/server/repositories/project-repository\";
import type { CreateMilestoneInput, UpdateMilestoneInput, CloseMilestoneInput } from \"@/schemas/milestone\";
import type { IssueId, MilestoneId, OrgId, ProjectId } from \"@/types/common\";
import type { Actor } from \"@/types/member\";
import type { Milestone, MilestoneWithProgress } from \"@/types/milestone\";
import { actorEnvelope, NotFoundError, projectResource, requireFound } from \"./_support\";

async function projectAccess(actor: Actor, orgId: OrgId, projectId: ProjectId, write: boolean): Promise<void> {
  const project = requireFound(await projectRepo.findProjectById(orgId, projectId), \"Project\", projectId);
  assertCan(actor, write ? \"project:update\" : \"project:read\", projectResource(project));
  if (write) assertNotArchived(\"Project\", project.id, project);
}
function find(orgId: OrgId, milestoneId: MilestoneId): Milestone {
  return requireFound(milestoneRepo.findMilestoneById(orgId, milestoneId), \"Milestone\", milestoneId);
}
/** Shared by issue creation, assignment, and closing; always scoped to the parent project. */
export function requireOpenMilestone(orgId: OrgId, projectId: ProjectId, milestoneId: MilestoneId): Milestone {
  const milestone = find(orgId, milestoneId);
  if (milestone.projectId "'!== projectId) throw new NotFoundError("Milestone", milestoneId);
  if (milestone.closedAt !== null) throw new MilestoneStateError("closed");
  return milestone;
}
export async function createMilestone(actor: Actor, input: CreateMilestoneInput): Promise<Milestone> {
  assertOrgScope(actor, input.orgId);
  await projectAccess(actor, input.orgId, input.projectId, true);
  const milestone = milestoneRepo.insertMilestone(input);
  await emit("milestone.created", { ...actorEnvelope(actor), milestoneId: milestone.id, projectId: milestone.projectId });
  return milestone;
}
export async function updateMilestone(actor: Actor, input: UpdateMilestoneInput): Promise<Milestone> {
  assertOrgScope(actor, input.orgId);
  const before = find(input.orgId, input.milestoneId);
  await projectAccess(actor, input.orgId, before.projectId, true);
  return milestoneRepo.updateMilestone(before, input);
}
export async function closeMilestone(actor: Actor, input: CloseMilestoneInput): Promise<{ milestone: Milestone; movedIssueIds: readonly IssueId[] }> {
  assertOrgScope(actor, input.orgId);
  const before = find(input.orgId, input.milestoneId);
  await projectAccess(actor, input.orgId, before.projectId, true);
  if (before.closedAt !== null) throw new MilestoneStateError("closed");
  const target = input.moveOpenIssuesTo ?? null;
  if (target === before.id) throw new NotFoundError("Milestone", target);
  if (target !== null) requireOpenMilestone(input.orgId, before.projectId, target);
  const result = milestoneRepo.closeMilestone(before, target);
  await emit("milestone.closed", { ...actorEnvelope(actor), milestoneId: before.id, projectId: before.projectId, movedToMilestoneId: target, movedIssueIds: result.movedIssueIds });
  return result;
}
export async function reopenMilestone(actor: Actor, orgId: OrgId, milestoneId: MilestoneId): Promise<Milestone> {
  assertOrgScope(actor, orgId);
  const before = find(orgId, milestoneId);
  await projectAccess(actor, orgId, before.projectId, true);
  const milestone = milestoneRepo.reopenMilestone(before);
  await emit("milestone.reopened", { ...actorEnvelope(actor), milestoneId, projectId: before.projectId });
