    if (current.closedAt === null) throw new MilestoneStateError("already_open");
    assertRoom(before.orgId, before.projectId);
    return toMilestone(tx.update(milestones).set({ closedAt: null, updatedAt: toIsoTimestamp(new Date()) }).where(and(eq(milestones.orgId, before.orgId), eq(milestones.id, before.id))).returning().get());
