    const milestone = toMilestone(tx.update(milestones).set({ closedAt: stamp, updatedAt: stamp }).where(and(eq(milestones.orgId, before.orgId), eq(milestones.id, before.id))).returning().get());
    return { milestone, movedIssueIds: moved.map(row => brandId<IssueId>(row.id)) };
