import { afterAll, beforeAll, describe, expect, it, vi } from \"vitest\";
vi.mock(\"@/lib/id\", () => import(\"../server/_support/doubles/id\"));
vi.mock(\"@/lib/logger\", async () => (await import(\"../server/_support/doubles/misc\")).loggerModule);

import { subscribe } from \"@/lib/event-bus\";
import { isDomainError, toAppError } from \"@/lib/errors\";
import { MilestoneStateError } from \"@/lib/milestones\";
import { PermissionDeniedError } from \"@/lib/permissions\";
import { AlreadyArchivedError } from \"@/lib/soft-delete\";
import { TenantScopeError } from \"@/lib/tenant\";
import { createMilestoneSchema, closeMilestoneSchema } from \"@/schemas/milestone\";
import { activityFilterSchema } from \"@/schemas/activity\";
import { updateNotificationPreferenceSchema } from \"@/schemas/notification\";
import * as issueRepo from \"@/server/repositories/issue-repository\";
import * as projectRepo from \"@/server/repositories/project-repository\";
import * as service from \"@/server/services/milestone-service\";
import * as issueService from \"@/server/services/issue-service\";
import { registerActivityListeners, listActivity } from \"@/server/services/activity-service\";
import { listNotifications, updatePreference } from \"@/server/services/notification-service\";
import { NotFoundError } from \"@/server/services/_support\";
import { toIsoTimestamp, type MilestoneId } from \"@/types/common\";
import { createTenant, issueInput, useTemporaryDatabase, type Tenant } from \"../server/_support/fixtures\";

let cleanup: () => void;
let detach: () => void;
let tenant: Tenant;
let other: Tenant;
beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  tenant = await createTenant(\"milestones\");
  other = await createTenant(\"milestone-other\");
  detach = registerActivityListeners();
});
afterAll(() => { detach(); cleanup(); });
const create = (name: string, targetDate: string | null = null, t = tenant) => service.createMilestone(t.actors.owner, createMilestoneSchema.parse({ orgId: t.org.id, projectId: t.project.id, name, targetDate }));

describe(\"milestones\", () => {
  it(\"persists changes, normalizes name uniqueness across closed rows, and scopes names to a project\", async () => {
    const m = await create(\"Release\");
    await expect(create(\"  rELEASe \")).rejects.toMatchObject({ reason: \"name_taken\" });
    const next = await create(\"Next\");
    await expect(service.updateMilestone(tenant.actors.owner, { orgId: tenant.org.id, milestoneId: next.id, name: \" RELEASE \" })).rejects.toMatchObject({ reason: \"name_taken\" });
    const renamed = await service.updateMilestone(tenant.actors.owner, { orgId: tenant.org.id, milestoneId: m.id, name: \"Launch\", targetDate: toIsoTimestamp(\"2020-01-01\") });
    expect(renamed.name).toBe(\"Launch\");
    await service.closeMilestone(tenant.actors.owner, closeMilestoneSchema.parse({ orgId: tenant.org.id, milestoneId: m.id }));
    await expect(create(\" launch \")).rejects.toMatchObject({ reason: \"name_taken\" });
    expect((await create(\"Launch\", null, other)).name).toBe(\"Launch\");
    expect((await service.getMilestone(tenant.actors.viewer, tenant.org.id, m.id)).milestone.targetDate).toBe(toIsoTimestamp(\"2020-01-01\"));
  });

  it(\"refuses invalid assignment and close targets without mutations or events\", async () => {
    const source = await create(\"Source\");
    const closed = await create(\"Closed target\");
    await service.closeMilestone(tenant.actors.owner, { orgId: tenant.org.id, milestoneId: closed.id, moveOpenIssuesTo: null });
    const foreign = await create(\"Foreign\", null, other);
    const localOtherProject = await projectRepo.insertProject({ orgId: tenant.org.id, name: \"Second\", slug: \"second\", key: \"SEC\", description: null, visibility: \"org\", leadId: null, color: \"#ffffff\", targetDate: null });
    const wrongProject = await service.createMilestone(tenant.actors.owner, { orgId: tenant.org.id, projectId: localOtherProject.id, name: \"Elsewhere\", targetDate: null });
    const issue = await issueService.createIssue(tenant.actors.member, { ...issueInput(tenant.org.id, tenant.project.id), milestoneId: source.id });
    const onClose = vi.fn(); const onCreate = vi.fn();
    const offClose = subscribe(\"milestone.closed\", onClose); const offCreate = subscribe(\"issue.created\", onCreate);
    const count = await issueRepo.countIssues(tenant.org.id, tenant.project.id);
    try {
      for (const target of [closed.id, source.id, foreign.id, wrongProject.id, \"01HZZZMMMMMMMMMMMMMMMMMMMM\" as MilestoneId]) {
        await expect(service.closeMilestone(tenant.actors.owner, { orgId: tenant.org.id, milestoneId: source.id, moveOpenIssuesTo: target })).rejects.toBeInstanceOf(target === closed.id ? MilestoneStateError : NotFoundError);
      }
      for (const target of [closed.id, foreign.id, wrongProject.id]) {
        await expect(issueService.createIssue(tenant.actors.member, { ...issueInput(tenant.org.id, tenant.project.id), milestoneId: target })).rejects.toBeInstanceOf(target === closed.id ? MilestoneStateError : NotFoundError);
        await expect(issueService.setIssueMilestone(tenant.actors.member, { orgId: tenant.org.id, issueId: issue.id, milestoneId: target })).rejects.toBeInstanceOf(target === closed.id ? MilestoneStateError : NotFoundError);
      }
      expect(await issueRepo.countIssues(tenant.org.id, tenant.project.id)).toBe(count);
      expect((await issueRepo.findIssueById(tenant.org.id, issue.id))?.milestoneId).toBe(source.id);
      expect((await service.getMilestone(tenant.actors.viewer, tenant.org.id, source.id)).milestone.closedAt).toBeNull();
      expect(onClose).not.toHaveBeenCalled(); expect(onCreate).not.toHaveBeenCalled();
    } finally { offClose(); offCreate(); }
  });

  it(\"counts all live issues, moves only open live issues, and audits and alerts once\", async () => {
    const t = await createTenant(\"milestone-close\");
    const source = await create(\"Sprint\", \"2020-01-01T00:00:00.000Z\", t);
    const target = await create(\"Following\", null, t);
    const issues = [];
    for (let index = 0; index < 110; index++) {
      issues.push(await issueService.createIssue(t.actors.member, { ...issueInput(t.org.id, t.project.id, { assigneeId: index === 0 ? t.userIds.member : index === 1 ? t.userIds.owner : null }), milestoneId: source.id }));
    }
    await issueService.changeIssueStatus(t.actors.member, { orgId: t.org.id, issueId: issues[2].id, status: \"done\" });
    await issueService.changeIssueStatus(t.actors.member, { orgId: t.org.id, issueId: issues[3].id, status: \"canceled\" });
    await issueService.archiveIssue(t.actors.owner, t.org.id, issues[4].id);
    expect(await service.getMilestone(t.actors.viewer, t.org.id, source.id)).toMatchObject({ progress: { total: 109, open: 107, closed: 2 }, overdue: true });
    const event = vi.fn(); const off = subscribe(\"milestone.closed\", event);
    const result = await service.closeMilestone(t.actors.owner, { orgId: t.org.id, milestoneId: source.id, moveOpenIssuesTo: target.id });
    off();
    expect(result.movedIssueIds).toHaveLength(107);
    expect(event).toHaveBeenCalledTimes(1);
    for (const index of [2, 3, 4]) expect((await issueRepo.findIssueById(t.org.id, issues[index].id))?.milestoneId).toBe(source.id);
    expect((await issueRepo.findIssueById(t.org.id, issues[0].id))?.milestoneId).toBe(target.id);
    const alerts = await listNotifications(t.actors.member, { orgId: t.org.id, recipientId: t.userIds.member, kind: [\"issue_milestone_changed\"], unreadOnly: false, limit: 100 });
    expect(alerts.items).toHaveLength(1);
    const own = await listNotifications(t.actors.owner, { orgId: t.org.id, recipientId: t.userIds.owner, kind: [\"issue_milestone_changed\"], unreadOnly: false, limit: 100 });
    expect(own.items).toHaveLength(0);
    const audit = await listActivity(t.actors.owner, activityFilterSchema.parse({ orgId: t.org.id, action: [\"milestone.closed\"], subjectKind: \"milestone\" }));
    expect(audit.items).toHaveLength(1);
    expect(audit.items[0]).toMatchObject({ subjectId: source.id, projectId: t.project.id, actorId: t.userIds.owner });
    await expect(service.closeMilestone(t.actors.owner, { orgId: t.org.id, milestoneId: source.id, moveOpenIssuesTo: null })).rejects.toMatchObject({ reason: \"closed\" });
    await service.reopenMilestone(t.actors.owner, t.org.id, source.id);
    await expect(service.reopenMilestone(t.actors.owner, t.org.id, source.id)).rejects.toMatchObject({ reason: \"already_open\" });
  });

  it(\"applies notification preferences and detaches issues when no target is named\", async () => {
    const m = await create(\"Muted\");
    const issue = await issueService.createIssue(tenant.actors.member, { ...issueInput(tenant.org.id, tenant.project.id, { assigneeId: tenant.userIds.member }), milestoneId: m.id });
    await updatePreference(tenant.actors.member, updateNotificationPreferenceSchema.parse({ orgId: tenant.org.id, userId: tenant.userIds.member, kind: \"issue_milestone_changed\", inApp: false, email: false, digestOnly: false }));
    await service.closeMilestone(tenant.actors.owner, { orgId: tenant.org.id, milestoneId: m.id, moveOpenIssuesTo: null });
    expect((await issueRepo.findIssueById(tenant.org.id, issue.id))?.milestoneId).toBeNull();
    expect((await listNotifications(tenant.actors.member, { orgId: tenant.org.id, recipientId: tenant.userIds.member, kind: [\"issue_milestone_changed\"], unreadOnly: false, limit: 100 })).items).toHaveLength(0);
  });

  it(\"enforces the cap on creation and reopening while allowing closed milestones\", async () => {
    const t = await createTenant(\"milestone-cap\");
    const rows = [];
    for (let i = 0; i < 10; i++) rows.push(await create("'`M${i}`, null, t));
    await expect(create("Overflow", null, t)).rejects.toMatchObject({ reason: "too_many_open" });
    await service.closeMilestone(t.actors.owner, { orgId: t.org.id, milestoneId: rows[0].id, moveOpenIssuesTo: null });
    const extra = await create("Extra", null, t);
    await expect(service.reopenMilestone(t.actors.owner, t.org.id, rows[0].id)).rejects.toMatchObject({ reason: "too_many_open" });
    await service.closeMilestone(t.actors.owner, { orgId: t.org.id, milestoneId: extra.id, moveOpenIssuesTo: null });
    expect((await service.reopenMilestone(t.actors.owner, t.org.id, rows[0].id)).closedAt).toBeNull();
  });

  it("enforces tenant, permission, and archive guards while keeping archived milestones readable", async () => {
    const t = await createTenant("milestone-guards");
    const m = await create("Guarded", null, t);
    const issue = await issueService.createIssue(t.actors.member, issueInput(t.org.id, t.project.id));
    await expect(service.listMilestones(t.actors.viewer, other.org.id, other.project.id)).rejects.toBeInstanceOf(TenantScopeError);
    const foreign = (await service.listMilestones(other.actors.viewer, other.org.id, other.project.id))[0].milestone;
    await expect(service.getMilestone(t.actors.owner, t.org.id, foreign.id)).rejects.toBeInstanceOf(NotFoundError);
    await expect(service.createMilestone(t.actors.viewer, { orgId: t.org.id, projectId: t.project.id, name: "No", targetDate: null })).rejects.toBeInstanceOf(PermissionDeniedError);
    await issueService.archiveIssue(t.actors.owner, t.org.id, issue.id);
    await expect(issueService.setIssueMilestone(t.actors.member, { orgId: t.org.id, issueId: issue.id, milestoneId: m.id })).rejects.toBeInstanceOf(AlreadyArchivedError);
    await issueRepo.restoreIssue(t.org.id, issue.id);
    await projectRepo.archiveProject(t.org.id, t.project.id);
    for (const operation of [
      () => create("No", null, t),
      () => service.updateMilestone(t.actors.owner, { orgId: t.org.id, milestoneId: m.id, name: "No" }),
      () => service.closeMilestone(t.actors.owner, { orgId: t.org.id, milestoneId: m.id, moveOpenIssuesTo: null }),
      () => service.reopenMilestone(t.actors.owner, t.org.id, m.id),
      () => issueService.setIssueMilestone(t.actors.member, { orgId: t.org.id, issueId: issue.id, milestoneId: null }),
    ]) await expect(operation()).rejects.toBeInstanceOf(AlreadyArchivedError);
    expect(await service.listMilestones(t.actors.viewer, t.org.id, t.project.id)).toHaveLength(1);
  });

  it("maps state errors as domain conflicts", () => {
    const error = new MilestoneStateError("closed");
    expect(isDomainError(error)).toBe(true);
    expect(toAppError(error)).toMatchObject({ code: "conflict", meta: { reason: "closed" } });
  });
});
